const https = require('https');
const fs = require('fs');
const path = require('path');

const domain = $node["Code6"].json.raw.MARQUE;

// ── Sanitize : remplacer les caractères interdits Windows ──────
// Interdits : \ / : * ? " < > |
const safeDomain = domain.replace(/[\\/:*?"<>|]/g, '_');

const token = "1idRFj7tTX4nczRzZdZ";

// Créer le dossier pour ce domain (avec nom sanitisé)
const basePath = 'C:\\hicham\\data\\images_brand';
const domainFolder = path.join(basePath, safeDomain);

// Créer dossiers si inexistants
if (!fs.existsSync(basePath)) fs.mkdirSync(basePath, { recursive: true });
if (!fs.existsSync(domainFolder)) fs.mkdirSync(domainFolder, { recursive: true });

function downloadImage(url) {
  return new Promise((resolve, reject) => {
    const makeRequest = (targetUrl, redirectCount = 0) => {
      if (redirectCount > 5) return reject(new Error('Trop de redirections'));
      const lib = targetUrl.startsWith('https') ? require('https') : require('http');
      lib.get(targetUrl, (res) => {
        if (res.statusCode === 301 || res.statusCode === 302) {
          return makeRequest(res.headers.location, redirectCount + 1);
        }
        if (res.statusCode !== 200) {
          return reject(new Error(`HTTP ${res.statusCode}`));
        }
        const chunks = [];
        res.on('data', chunk => chunks.push(chunk));
        res.on('end', () => resolve(Buffer.concat(chunks)));
        res.on('error', reject);
      }).on('error', reject);
    };
    makeRequest(url);
  });
}

// Appel API Brandfetch
const result = await new Promise((resolve, reject) => {
  const options = {
    hostname: 'api.brandfetch.io',
    path: `/v2/search/${encodeURIComponent(domain)}`,
    method: 'GET',
    headers: { 'Authorization': `Bearer ${token}` }
  };
  https.get(options, (res) => {
    let body = '';
    res.on('data', chunk => body += chunk);
    res.on('end', () => {
      try { resolve({ status: res.statusCode, data: JSON.parse(body) }); }
      catch(e) { resolve({ status: res.statusCode, data: [] }); }
    });
  }).on('error', reject);
});

if (result.status === 404 || !result.data || result.data.length === 0) {
  return [{ json: {
    domain,
    safe_domain: safeDomain,
    logo_existe: false,
    folder_path: domainFolder,
    message: `Aucun logo pour ${domain}`
  }}];
}

function getExtension(url) {
  if (url.includes('.svg'))  return { mimeType: 'image/svg+xml', ext: 'svg' };
  if (url.includes('.jpg') || url.includes('.jpeg')) return { mimeType: 'image/jpeg', ext: 'jpg' };
  if (url.includes('.webp')) return { mimeType: 'image/webp', ext: 'webp' };
  return { mimeType: 'image/png', ext: 'png' };
}

// Télécharger + sauvegarder TOUS les logos
const items = await Promise.all(
  result.data.map(async (brand, index) => {
    let logoUrl = brand.icon;
    if (!logoUrl && brand.logos?.length > 0) {
      for (const logo of brand.logos) {
        if (logo.formats?.length > 0) { logoUrl = logo.formats[0].src; break; }
      }
    }

    if (!logoUrl) {
      return {
        json: {
          domain,
          safe_domain: safeDomain,
          brand_name: brand.name,
          brand_domain: brand.domain,
          brand_id: brand.brandId,
          rank: index + 1,
          logo_existe: false,
          folder_path: domainFolder,
          message: `Pas d'URL pour ${brand.name}`
        }
      };
    }

    try {
      const imageBuffer = await downloadImage(logoUrl);
      const { mimeType, ext } = getExtension(logoUrl);

      // Sanitiser aussi le brand.domain pour le nom de fichier
      const safeBrandDomain = (brand.domain || safeDomain).replace(/[\\/:*?"<>|]/g, '_');
      const fileName = `${safeBrandDomain}_${index + 1}.${ext}`;
      const filePath = path.join(domainFolder, fileName);

      // Écriture sur disque
      fs.writeFileSync(filePath, imageBuffer);

      return {
        json: {
          domain,
          safe_domain: safeDomain,
          brand_name: brand.name,
          brand_domain: brand.domain,
          brand_id: brand.brandId,
          rank: index + 1,
          score: brand._score,
          quality_score: brand.qualityScore,
          claimed: brand.claimed,
          verified: brand.verified,
          logo_existe: true,
          logo_url: logoUrl,
          local_path: filePath,
          folder_path: domainFolder,
          file_name: fileName,
          binary_key: `logo_${index + 1}`,
          message: `✅ Sauvegardé : ${filePath}`
        },
        binary: {
          [`logo_${index + 1}`]: {
            data: imageBuffer.toString('base64'),
            mimeType,
            fileName,
            fileExtension: ext
          }
        }
      };
    } catch (e) {
      return {
        json: {
          domain,
          safe_domain: safeDomain,
          brand_name: brand.name,
          brand_domain: brand.domain,
          rank: index + 1,
          logo_existe: false,
          logo_url: logoUrl,
          folder_path: domainFolder,
          download_error: e.message,
          message: `❌ Échec : ${brand.name} — ${e.message}`
        }
      };
    }
  })
);

return items;

// Input: tableau JSON avec domain, logo_existe, data[], message
const items = $input.all();
const output = [];

for (const item of items) {
  const { domain, logo_existe, message } = item.json;
  const brands = item.json.data || [];

  for (const brand of brands) {
    output.push({
      json: {
        search_domain: domain,
        logo_existe: logo_existe,
        search_message: message,
        brand_id: brand.brandId,
        brand_name: brand.name,
        brand_domain: brand.domain,
        brand_icon: brand.icon,
        claimed: brand.claimed ?? false,
        verified: brand.verified ?? null,
        score: brand._score,
        quality_score: brand.qualityScore,
      }
    });
  }
}

return output;

// Récupère les items venant du node précédent (dynamique)
const items = $input.all();

function cleanBrand(value) {
  if (!value) return value;
  return value
    .replace(/\u00A0/g, ' ')   // NBSP -> espace normal
    .replace(/\s+/g, ' ')      // espaces multiples -> un seul
    .trim()                    // supprime début/fin
    .toUpperCase();
}

return items.map(item => {
  return {
    json: {
      ...item.json,
      marque_x3: cleanBrand(item.json.marque_x3)
    }
  };
});

const seen = new Set();
const result = [];

for (const item of $input.all()) {
  const marque = String(item.json.MARQUE ?? '')
    .replace(/\s+/g, ' ')   // plusieurs espaces -> un seul
    .trim();                // enlève les espaces au début et à la fin

  if (!marque) continue;                 // ignore les valeurs vides
  if (seen.has(marque)) continue;        // ignore les doublons
  seen.add(marque);

  result.push({ json: { MARQUE: marque } });
}

return result;
